-- Stage 9: the monitoring map is now the expert's 3 dive sites in Samal (adviser + expert, 2026-11-04).
--   Site 1 · Tambo, Site 2 · Adecor, Site 3 · Linosutan. One zone (Samal), no parts.
--   Side borders = barangay borders (NAMRIA/PSA via OCHA COD-AB). Outer edge = the drop-off at 7 m depth
--   (Allen Coral Atlas 2020, Bathymetry - composite depth, CC BY 4.0); Site 3 widened 300 m past it.
--   Generated by zone_maps/samal_sites (spec.json, site_lookup_runs.csv). Do not edit rows by hand.
-- The old Davao Gulf map (75 boxes cots-davao-gulf-v1, 17,841 parts cots-davao-gulf-v2) is DELETED
-- (user, 2026-11-04: "just delete it"). A hosted backup is taken before this is pushed
-- (backups/2026-11-04_2320_*).
-- Safety: if any record or assignment still uses an old box or part, nothing is deleted and the change stops.

-- 0. Delete the 2 test records saved on 2026-11-03 in old part A1-67 (Panabo) and everything attached to
--    them: removals, photos (database rows), AI detections, verification jobs, history events and their
--    notifications (user, 2026-11-04 23:18: "Delete them they are not needed"). Only these 2 records.
--    The photo FILES stay in Supabase Storage (they cannot be deleted from SQL); see the notes.
--    Record history is normally protected; the protection is switched off only for these rows and back on.
create temporary table stage9_test_captures (id uuid primary key);
select c.id from public.captures c join public.monitoring_areas a on a.id = c.area_id
where c.id in ('d4e2aa0c-ee9d-55cc-b4af-f98df7e9ff98', '48076831-c51d-5a26-beb8-3812934aaf3e')
  and a.geography_version in ('cots-davao-gulf-v1', 'cots-davao-gulf-v2');
create temporary table stage9_test_eliminations as
  select e.id, e.encounter_id from public.eliminations e where e.capture_id in (select id from stage9_test_captures);
create temporary table stage9_test_variants as
  select ce.variant_id from public.capture_evidence ce where ce.capture_id in (select id from stage9_test_captures)
  union select ee.variant_id from public.elimination_evidence ee where ee.elimination_id in (select id from stage9_test_eliminations);
create temporary table stage9_test_assets as
  select distinct v.asset_id from public.media_variants v where v.id in (select variant_id from stage9_test_variants);
create temporary table stage9_test_encounters as
  select c.encounter_id as id from public.captures c where c.id in (select id from stage9_test_captures) and c.encounter_id is not null
  union select encounter_id from stage9_test_eliminations where encounter_id is not null;
create temporary table stage9_test_events as
  select w.id from public.workflow_events w where w.capture_id in (select id from stage9_test_captures);

alter table public.workflow_events disable trigger immutable_history;
alter table public.encounters disable trigger immutable_history;
alter table public.expert_decisions disable trigger immutable_history;
alter table public.survey_captures disable trigger immutable_history;

delete from public.notifications where event_id in (select id from stage9_test_events);
delete from public.workflow_events where id in (select id from stage9_test_events);
delete from public.expert_decisions where capture_id in (select id from stage9_test_captures);
delete from public.survey_captures where capture_id in (select id from stage9_test_captures);
delete from public.elimination_evidence where elimination_id in (select id from stage9_test_eliminations);
delete from public.eliminations where id in (select id from stage9_test_eliminations);
delete from public.capture_evidence where capture_id in (select id from stage9_test_captures);
delete from public.detection_items where capture_id in (select id from stage9_test_captures);
delete from public.captures where id in (select id from stage9_test_captures);
delete from public.encounters where id in (select id from stage9_test_encounters)
  and not exists (select 1 from public.captures c where c.encounter_id = encounters.id)
  and not exists (select 1 from public.eliminations e where e.encounter_id = encounters.id);
delete from public.media_variants v where v.id in (select variant_id from stage9_test_variants)
  and not exists (select 1 from public.capture_evidence x where x.variant_id = v.id)
  and not exists (select 1 from public.elimination_evidence x where x.variant_id = v.id)
  and not exists (select 1 from public.survey_evidence x where x.variant_id = v.id);
delete from public.media_assets m where m.id in (select asset_id from stage9_test_assets)
  and not exists (select 1 from public.media_variants v where v.asset_id = m.id);

alter table public.workflow_events enable trigger immutable_history;
alter table public.encounters enable trigger immutable_history;
alter table public.expert_decisions enable trigger immutable_history;
alter table public.survey_captures enable trigger immutable_history;
drop table stage9_test_captures, stage9_test_eliminations, stage9_test_variants, stage9_test_assets,
  stage9_test_encounters, stage9_test_events;

-- 1. Stop if anything still uses the old map.
do $$
declare n_captures integer; n_assignments integer;
begin
  select count(*) into n_captures from public.captures c
    join public.monitoring_areas a on a.id = c.area_id
    where a.geography_version in ('cots-davao-gulf-v1', 'cots-davao-gulf-v2');
  select count(*) into n_assignments from public.follow_up_assignments f
    join public.monitoring_areas a on a.id = f.area_id
    where a.geography_version in ('cots-davao-gulf-v1', 'cots-davao-gulf-v2');
  if n_captures > 0 or n_assignments > 0 then
    raise exception 'Stage 9 stopped: % records and % follow-up assignments still use the old Davao Gulf map. Nothing was deleted.',
      n_captures, n_assignments;
  end if;
end $$;

-- 2. Delete the old map.
delete from cots_private.area_cells;
delete from public.monitoring_areas where geography_version in ('cots-davao-gulf-v1', 'cots-davao-gulf-v2');

