-- 4. Which site each spot of water belongs to (same 30 m grid as before; a cell belongs to a site when
--    at least half of it is inside the site).
create temporary table site_cell_codes (iy integer, ix_start integer, ix_end integer, code text);
select c.iy, c.ix_start, c.ix_end, a.id from site_cell_codes c
join public.monitoring_areas a on a.code = c.code and a.geography_version = 'cots-samal-sites-v1';
drop table site_cell_codes;

-- 5. Names in messages: "Site 2 · Adecor" instead of a code.
create or replace function cots_private.area_short_code(aid uuid) returns text
language sql stable security definer set search_path = '' as $$
  select coalesce((select a.name from public.monitoring_areas a where a.id = aid), 'another site')
$$;
revoke all on function cots_private.area_short_code(uuid) from public, anon, authenticated;

-- 6. Location checks for the sites (same rules as Stages 6-7; test areas are not checked).
--    The code after COTS_AREA_MISMATCH: is the site code (S1, S2, S3); the app reads it.
create or replace function cots_private.check_capture_area() returns trigger
language plpgsql security definer set search_path = '' as $$
declare a public.monitoring_areas; found uuid;
begin
  select * into a from public.monitoring_areas where id = new.area_id;
  if not a.active then
    raise exception 'COTS_AREA_INACTIVE: This site is no longer used. Please update the app.' using errcode = '23514';
  end if;
  if a.geography_version = 'cots-samal-sites-v1' and new.latitude is null then
    raise exception 'COTS_AREA_NO_LOCATION: A location is required. Turn on location, or use a photo that has GPS.' using errcode = '23514';
  end if;
  if a.geography_version = 'cots-samal-sites-v1' then
    found := cots_private.area_at(new.latitude::double precision, new.longitude::double precision);
    if found is null then
      raise exception 'COTS_AREA_OUTSIDE: This photo''s location is outside every site (on land or past the drop-off).' using errcode = '23514';
    elsif found <> new.area_id then
      raise exception 'COTS_AREA_MISMATCH:%: This photo was taken in %, not %.',
        (select m.code from public.monitoring_areas m where m.id = found),
        cots_private.area_short_code(found), a.name using errcode = '23514';
    end if;
  end if;
  return new;
end $$;

create or replace function cots_private.check_survey_area() returns trigger
language plpgsql security definer set search_path = '' as $$
declare a public.monitoring_areas; found uuid;
begin
  select ma.* into a from public.follow_up_assignments f join public.monitoring_areas ma on ma.id = f.area_id
  where f.id = new.assignment_id;
  if a.geography_version = 'cots-samal-sites-v1' and new.latitude is not null then
    found := cots_private.area_at(new.latitude::double precision, new.longitude::double precision);
    if found is null then
      raise exception 'COTS_AREA_OUTSIDE: This visit''s location is outside every site (on land or past the drop-off).' using errcode = '23514';
    elsif found <> a.id then
      raise exception 'COTS_AREA_MISMATCH:%: This visit was recorded in %, not %.',
        (select m.code from public.monitoring_areas m where m.id = found),
        cots_private.area_short_code(found), a.name using errcode = '23514';
    end if;
  end if;
  return new;
end $$;

create or replace function cots_private.check_survey_capture_area() returns trigger
language plpgsql security definer set search_path = '' as $$
declare visit_area uuid; photo_area uuid; v text;
begin
  select f.area_id into visit_area from public.follow_up_surveys s
    join public.follow_up_assignments f on f.id = s.assignment_id where s.id = new.survey_id;
  select c.area_id into photo_area from public.captures c where c.id = new.capture_id;
  select ma.geography_version into v from public.monitoring_areas ma where ma.id = visit_area;
  if v = 'cots-samal-sites-v1' and photo_area is distinct from visit_area then
    raise exception 'COTS_AREA_MISMATCH:%: Some photos were taken in %, not %. Please submit them as a separate visit for %.',
      (select m.code from public.monitoring_areas m where m.id = photo_area),
      cots_private.area_short_code(photo_area), cots_private.area_short_code(visit_area),
      cots_private.area_short_code(photo_area) using errcode = '23514';
  end if;
  return new;
end $$;

revoke all on function cots_private.check_capture_area() from public, anon, authenticated;
revoke all on function cots_private.check_survey_area() from public, anon, authenticated;
revoke all on function cots_private.check_survey_capture_area() from public, anon, authenticated;
